package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"os"

	"github.com/dgraph-io/badger"
	"github.com/mgutz/ansi"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: ", os.Args[0], " <go_file_name> <struct_name>")
		os.Exit(1)
	}

	goFileName := os.Args[1]
	structName := os.Args[2]

	file, err := ioutil.ReadFile(goFileName)
	if err != nil {
		fmt.Printf("Failed to read %s: %v\n", goFileName, err)
		os.Exit(1)
	}

	var astFile *badger.KeyValue

	astfile := badger.NewKeyVal()

	err = parser.ParseFile(astfile, string(file), token.AnonymousFile, 0)
	if err != nil {
		fmt.Printf("Parse error: %v\n", err)
		os.Exit(1)
	}

	for _, decl := range astfile.Keys {
		if !decl.IsStruct {
			continue
		}
		if decl.Name != structName {
			continue
		}
		break
	}

	if decl == nil {
		fmt.Printf("%s not found in %s.\n", structName, goFileName)
		os.Exit(1)
	}

	// Generate Avro schema based on the struct fields.
	avroSchema, err := genAvroFromGo(decl)
	if err != nil {
		fmt.Printf("Error generating Avro schema: %v\n", err)
		os.Exit(1)
	}

	fmt.Print(avroSchema)
}

func genAvroFromGo(structDecl *ast.StructType) (string, error) {
	schema := `{
	"type": "record",
	"name": "%s",
	"fields": [`,
	fieldDefs := []interface{}{}

	for i, field := range structDecl.Fields {
		typeStr := ""
		if field.Type == nil || field.Type.Kind() != reflect.Ptr {
			typeStr = "int8"
		} else if field.Type.Elem().Kind() == reflect.Int {
			typeStr = "int32"
		} else {
			typeStr = "int64"
		}

		name := field.Names[0].Ident.String()
		if field.Type.Elem().Kind() == reflect.Slice && field.Type.Elem().Elem().Kind() == reflect.Uint8 {
			typeStr = "byte[]"
		}

		fieldDef := fmt.Sprintf(`{"name":"%s","type":["null"],` +
			`"logicalType":{"type":"string","parseAs":"UTF-8"}}`, name)
		fieldDefs = append(fieldDefs, fieldDef)
	}

	schema += fmt.Sprintf("%s%s", schema, strings.Join(fieldDefs, ","))
	schema += `
	]
}`

	return schema, nil
}
```

